//! Every file in `spec/examples/` must parse as the type its name starts with
//! and survive a round trip unchanged. The Python package runs the same check,
//! so a schema change that the two languages read differently fails here.

// Integration tests: a failed unwrap is the failure (clippy.toml covers only #[test] functions and test modules).
#![allow(clippy::unwrap_used)]

use std::fs;
use std::path::Path;

use serde_json::Value;

// `parse_as`, generated by build.rs with one arm per spec type.
include!(concat!(env!("OUT_DIR"), "/spec_parse_as.rs"));

/// Equal, treating `212` and `212.0` as the same number.
fn same(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Number(x), Value::Number(y)) => x.as_f64() == y.as_f64(),
        (Value::Array(x), Value::Array(y)) => x.len() == y.len() && x.iter().zip(y).all(|(x, y)| same(x, y)),
        (Value::Object(x), Value::Object(y)) => {
            x.len() == y.len() && x.iter().all(|(key, x)| y.get(key).is_some_and(|y| same(x, y)))
        }
        _ => a == b,
    }
}

#[test]
fn examples_match_their_types() {
    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../spec/examples");
    let mut checked = 0;
    for entry in fs::read_dir(&dir).unwrap() {
        let path = entry.unwrap().path();
        let file_name = path.file_name().unwrap().to_string_lossy().into_owned();
        let Some(type_name) = file_name.strip_suffix(".json").and_then(|stem| stem.split('.').next()) else {
            continue;
        };
        let text = fs::read_to_string(&path).unwrap();
        let parsed = parse_as(type_name, &text)
            .unwrap_or_else(|| panic!("{file_name}: no spec type called {type_name}"))
            .unwrap_or_else(|e| panic!("{file_name}: {e}"));
        let original: Value = serde_json::from_str(&text).unwrap();
        assert!(
            same(&original, &parsed),
            "{file_name}: has fields that {type_name} does not define"
        );
        checked += 1;
    }
    assert!(checked > 0, "no examples found in {}", dir.display());
}
